const root = ($json && typeof $json === 'object') ? $json : {};
const payload = (root.body && typeof root.body === 'object') ? root.body : root;
const data = (payload.data && typeof payload.data === 'object') ? payload.data : {};
const key = (data.key && typeof data.key === 'object') ? data.key : {};

const unwrapMessage = (value, depth = 0) => {
  if (!value || typeof value !== 'object' || depth > 5) return {};
  if (value.ephemeralMessage?.message) return unwrapMessage(value.ephemeralMessage.message, depth + 1);
  if (value.viewOnceMessage?.message) return unwrapMessage(value.viewOnceMessage.message, depth + 1);
  if (value.viewOnceMessageV2?.message) return unwrapMessage(value.viewOnceMessageV2.message, depth + 1);
  if (value.documentWithCaptionMessage?.message) return unwrapMessage(value.documentWithCaptionMessage.message, depth + 1);
  return value;
};

const messageObject = unwrapMessage(data.message);
const textCandidates = [
  messageObject.conversation,
  messageObject.extendedTextMessage?.text,
];
const message = String(textCandidates.find((value) => typeof value === 'string' && value.trim()) || '').trim();

const remoteJid = String(key.remoteJid || '');
const remoteJidAlt = String(key.remoteJidAlt || '');
const directJid = [remoteJidAlt, remoteJid].find((value) => /@s\.whatsapp\.net$/i.test(value))
  || remoteJidAlt
  || remoteJid;
const phone = String(directJid.split('@')[0] || '').replace(/\D/g, '');
const event = String(payload.event || '').trim().toLowerCase();
const fromMe = key.fromMe === true || key.fromMe === 'true';
const isGroup = /@g\.us$/i.test(remoteJid);
const isBroadcast = /@broadcast$/i.test(remoteJid) || remoteJid === 'status@broadcast';
const messageId = String(key.id || '').trim();
const sourceMessageType = String(data.messageType || '').trim();
const instance = String(payload.instance || data.instance || 'Assistance').trim();
const pushName = String(data.pushName || '').trim();
const timestamp = String(data.messageTimestamp || payload.date_time || '').trim();

const isSupportedText = Boolean(
  event === 'messages.upsert'
  && !fromMe
  && !isGroup
  && !isBroadcast
  && phone
  && messageId
  && message
);

let rejectionReason = '';
if (event !== 'messages.upsert') rejectionReason = 'unsupported_event';
else if (fromMe) rejectionReason = 'outgoing_message';
else if (isGroup || isBroadcast) rejectionReason = 'non_customer_chat';
else if (!phone) rejectionReason = 'missing_sender';
else if (!messageId) rejectionReason = 'missing_message_id';
else if (!message) rejectionReason = 'unsupported_or_empty_message';

return [{
  json: {
    phone,
    message,
    messageId,
    instance,
    pushName,
    messageType: isSupportedText ? 'text' : sourceMessageType,
    customer_phone: phone,
    customer_name: pushName,
    message_id: messageId,
    message_text: message,
    message_type: isSupportedText ? 'text' : sourceMessageType,
    message_timestamp: timestamp,
    source_message_type: sourceMessageType,
    event,
    remote_jid: remoteJid,
    from_me: fromMe,
    is_supported_text: isSupportedText,
    rejection_reason: rejectionReason,
  },
}];

